import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import {
  db,
  Role,
  VehicleStatus,
  DriverStatus,
  TripStatus,
  MaintenanceStatus
} from "./server/db.js";
import { isLicenseValid } from "./lib/licenseCheck.js";
import { vehicleSchema } from "./lib/validation/vehicle.js";
import { driverSchema } from "./lib/validation/driver.js";
import { tripSchema } from "./lib/validation/trip.js";
import { maintenanceSchema } from "./lib/validation/maintenance.js";
import { fuelSchema } from "./lib/validation/fuel.js";
import { expenseSchema } from "./lib/validation/expense.js";

const isProd = process.env.NODE_ENV === "production";
const PORT = 3000;

async function startServer() {
  const app = express();
  app.use(express.json());

  const validateBody = (schema: any) => {
    return (req: any, res: any, next: any) => {
      const result = schema.safeParse(req.body);
      if (!result.success) {
        const errorMsg = result.error.errors.map((e: any) => `${e.path.join(".")}: ${e.message}`).join(", ");
        res.status(400).json({ error: `Validation failed: ${errorMsg}` });
        return;
      }
      req.body = result.data;
      next();
    };
  };

  // Role authentication helper middleware
  const getRoleHeader = (req: express.Request): Role => {
    const role = req.headers["x-user-role"] as string;
    if (Object.values(Role).includes(role as Role)) {
      return role as Role;
    }
    // Default fallback to FLEET_MANAGER so it is fully functional for dev/unauthenticated
    return Role.FLEET_MANAGER;
  };

  const requireRoles = (roles: Role[]) => {
    return (req: express.Request, res: express.Response, next: express.NextFunction) => {
      const activeRole = getRoleHeader(req);
      if (!roles.includes(activeRole)) {
        res.status(403).json({
          error: `Access Denied: Your current role is '${activeRole}'. This action requires one of: ${roles.join(", ")}.`
        });
        return;
      }
      next();
    };
  };

  // --- API ROUTES ---

  // Auth / Users Session
  app.get("/api/users", (req, res) => {
    res.json(db.getUsers());
  });

  // 1. VEHICLES API
  app.get("/api/vehicles", (req, res) => {
    let vehicles = db.getVehicles();
    const { status, type, region } = req.query;

    if (status) vehicles = vehicles.filter(v => v.status === status);
    if (type) vehicles = vehicles.filter(v => v.type === type);
    if (region) vehicles = vehicles.filter(v => v.region === region);

    res.json(vehicles);
  });

  app.get("/api/vehicles/available", (req, res) => {
    const vehicles = db.getVehicles().filter(v => v.status === VehicleStatus.AVAILABLE);
    res.json(vehicles);
  });

  app.post("/api/vehicles", requireRoles([Role.FLEET_MANAGER]), validateBody(vehicleSchema), (req, res) => {
    try {
      const newVehicle = db.addVehicle({
        ...req.body,
        status: VehicleStatus.AVAILABLE
      });
      res.status(201).json(newVehicle);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  app.patch("/api/vehicles/:id", requireRoles([Role.FLEET_MANAGER]), (req, res) => {
    try {
      const updated = db.updateVehicle(req.params.id, req.body);
      res.json(updated);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  app.post("/api/vehicles/:id/retire", requireRoles([Role.FLEET_MANAGER]), (req, res) => {
    try {
      const retired = db.retireVehicle(req.params.id);
      res.json(retired);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  // 2. DRIVERS API
  app.get("/api/drivers", (req, res) => {
    let drivers = db.getDrivers();
    const { status } = req.query;

    if (status) drivers = drivers.filter(d => d.status === status);
    res.json(drivers);
  });

  app.get("/api/drivers/available", (req, res) => {
    const available = db.getDrivers().filter(d => {
      return d.status === DriverStatus.AVAILABLE && isLicenseValid(d.licenseExpiryDate);
    });
    res.json(available);
  });

  app.post("/api/drivers", requireRoles([Role.FLEET_MANAGER, Role.SAFETY_OFFICER]), validateBody(driverSchema), (req, res) => {
    try {
      const newDriver = db.addDriver({
        ...req.body,
        status: DriverStatus.AVAILABLE
      });
      res.status(201).json(newDriver);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  app.patch("/api/drivers/:id", requireRoles([Role.FLEET_MANAGER, Role.SAFETY_OFFICER]), (req, res) => {
    try {
      const updated = db.updateDriver(req.params.id, req.body);
      res.json(updated);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  app.patch("/api/drivers/:id/suspend", requireRoles([Role.SAFETY_OFFICER]), (req, res) => {
    try {
      const { suspend } = req.body;
      if (suspend === undefined) {
        res.status(400).json({ error: "Missing field 'suspend' (boolean)" });
        return;
      }
      const updated = db.suspendDriver(req.params.id, Boolean(suspend));
      res.json(updated);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  // 3. TRIPS API
  app.get("/api/trips", (req, res) => {
    let trips = db.getTrips();
    const { status } = req.query;

    if (status) trips = trips.filter(t => t.status === status);
    res.json(trips);
  });

  app.post("/api/trips", requireRoles([Role.DISPATCHER]), validateBody(tripSchema), (req, res) => {
    try {
      const trip = db.createTrip({
        ...req.body
      });
      res.status(201).json(trip);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  app.post("/api/trips/:id/dispatch", requireRoles([Role.DISPATCHER]), (req, res) => {
    try {
      const trip = db.dispatchTrip(req.params.id);
      res.json(trip);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  app.post("/api/trips/:id/complete", requireRoles([Role.DISPATCHER]), (req, res) => {
    try {
      const { endOdometerKm, fuelConsumedL, fuelCost, revenue } = req.body;
      if (endOdometerKm === undefined || fuelConsumedL === undefined || fuelCost === undefined) {
        res.status(400).json({ error: "Missing completion data (endOdometerKm, fuelConsumedL, fuelCost)" });
        return;
      }
      const trip = db.completeTrip(
        req.params.id,
        Number(endOdometerKm),
        Number(fuelConsumedL),
        Number(fuelCost),
        revenue !== undefined ? Number(revenue) : 0
      );
      res.json(trip);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  app.post("/api/trips/:id/cancel", requireRoles([Role.DISPATCHER]), (req, res) => {
    try {
      const trip = db.cancelTrip(req.params.id);
      res.json(trip);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  // 4. MAINTENANCE API
  app.get("/api/maintenance", (req, res) => {
    let logs = db.getMaintenanceLogs();
    const { vehicleId, status } = req.query;

    if (vehicleId) logs = logs.filter(l => l.vehicleId === vehicleId);
    if (status) logs = logs.filter(l => l.status === status);

    res.json(logs);
  });

  app.post("/api/maintenance", requireRoles([Role.FLEET_MANAGER]), validateBody(maintenanceSchema), (req, res) => {
    try {
      const { vehicleId, description, cost } = req.body;
      const log = db.openMaintenance(vehicleId, description, cost);
      res.status(201).json(log);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  app.post("/api/maintenance/:id/close", requireRoles([Role.FLEET_MANAGER]), (req, res) => {
    try {
      const { cost } = req.body;
      if (cost === undefined) {
        res.status(400).json({ error: "Missing cost field" });
        return;
      }
      const log = db.closeMaintenance(req.params.id, Number(cost));
      res.json(log);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  // 5. FUEL LOGS API
  app.get("/api/fuel-logs", (req, res) => {
    res.json(db.getFuelLogs());
  });

  app.post("/api/fuel-logs", requireRoles([Role.FLEET_MANAGER, Role.FINANCIAL_ANALYST, Role.DISPATCHER]), validateBody(fuelSchema), (req, res) => {
    try {
      const { vehicleId, liters, cost } = req.body;
      const log = db.addFuelLog(vehicleId, liters, cost);
      res.status(201).json(log);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  // 6. EXPENSES API
  app.get("/api/expenses", (req, res) => {
    res.json(db.getExpenses());
  });

  app.post("/api/expenses", requireRoles([Role.FLEET_MANAGER, Role.FINANCIAL_ANALYST]), validateBody(expenseSchema), (req, res) => {
    try {
      const newExpense = db.addExpense({
        ...req.body
      });
      res.status(201).json(newExpense);
    } catch (err: any) {
      res.status(400).json({ error: err.message });
    }
  });

  // 7. REPORTS & KPI API
  app.get("/api/reports/dashboard", (req, res) => {
    const vehicles = db.getVehicles();
    const drivers = db.getDrivers();
    const trips = db.getTrips();

    const activeVehicles = vehicles.filter(v => v.status !== VehicleStatus.RETIRED).length;
    const availableVehicles = vehicles.filter(v => v.status === VehicleStatus.AVAILABLE).length;
    const vehiclesInShop = vehicles.filter(v => v.status === VehicleStatus.IN_SHOP).length;
    const activeTrips = trips.filter(t => t.status === TripStatus.DISPATCHED).length;
    const pendingTrips = trips.filter(t => t.status === TripStatus.DRAFT).length;
    const driversOnDuty = drivers.filter(d => d.status === DriverStatus.AVAILABLE || d.status === DriverStatus.ON_TRIP).length;

    const utilization = activeVehicles > 0
      ? Math.round((vehicles.filter(v => v.status === VehicleStatus.ON_TRIP).length / activeVehicles) * 100)
      : 0;

    res.json({
      activeVehicles,
      availableVehicles,
      vehiclesInShop,
      activeTrips,
      pendingTrips,
      driversOnDuty,
      fleetUtilizationPercent: utilization
    });
  });

  app.get("/api/reports/analytics", (req, res) => {
    const vehicles = db.getVehicles();
    const trips = db.getTrips();
    const mLogs = db.getMaintenanceLogs();
    const fuelLogs = db.getFuelLogs();
    const expenses = db.getExpenses();

    const report = vehicles.map(vehicle => {
      // 1. Fuel Efficiency (planned Distance / liters)
      const vehicleTrips = trips.filter(t => t.vehicleId === vehicle.id && t.status === TripStatus.COMPLETED);
      const totalFuelTripLiters = vehicleTrips.reduce((acc, t) => acc + (t.fuelConsumedL ?? 0), 0);
      const totalDistanceTrip = vehicleTrips.reduce((acc, t) => acc + (t.plannedDistanceKm ?? 0), 0);

      // Manual logs too
      const manualFuelLiters = fuelLogs.filter(f => f.vehicleId === vehicle.id).reduce((acc, f) => acc + f.liters, 0);
      const totalFuelLiters = totalFuelTripLiters + manualFuelLiters;

      const fuelEfficiencyKmPerL = totalFuelLiters > 0
        ? Number((totalDistanceTrip / totalFuelLiters).toFixed(2))
        : 0;

      // 2. Operational Cost = Fuel Cost + Maintenance Cost + General Expenses
      const fuelCost = fuelLogs.filter(f => f.vehicleId === vehicle.id).reduce((acc, f) => acc + f.cost, 0);
      const maintenanceCost = mLogs.filter(m => m.vehicleId === vehicle.id).reduce((acc, m) => acc + m.cost, 0);
      const vehicleExpenses = expenses.filter(e => e.vehicleId === vehicle.id).reduce((acc, e) => acc + e.amount, 0);
      const operationalCost = fuelCost + maintenanceCost + vehicleExpenses;

      // 3. Vehicle ROI = (Total Trip Revenue - Operational Cost) / Vehicle Acquisition Cost
      const totalRevenue = trips.filter(t => t.vehicleId === vehicle.id && t.status === TripStatus.COMPLETED)
        .reduce((acc, t) => acc + (t.revenue ?? 0), 0);

      const netEarnings = totalRevenue - operationalCost;
      const roi = vehicle.acquisitionCost > 0
        ? Number((netEarnings / vehicle.acquisitionCost).toFixed(4))
        : 0;

      return {
        vehicleId: vehicle.id,
        name: vehicle.name,
        registrationNumber: vehicle.registrationNumber,
        type: vehicle.type,
        acquisitionCost: vehicle.acquisitionCost,
        totalDistanceKm: totalDistanceTrip,
        totalFuelLiters,
        fuelEfficiencyKmPerL,
        fuelCost,
        maintenanceCost,
        otherExpenses: vehicleExpenses,
        operationalCost,
        totalRevenue,
        roiPercent: Number((roi * 100).toFixed(2))
      };
    });

    res.json(report);
  });

  app.get("/api/reports/fuel-efficiency", (req, res) => {
    const vehicles = db.getVehicles();
    const trips = db.getTrips();
    const fuelLogs = db.getFuelLogs();

    const data = vehicles.map(vehicle => {
      const vehicleTrips = trips.filter(t => t.vehicleId === vehicle.id && t.status === TripStatus.COMPLETED);
      const totalDistance = vehicleTrips.reduce((acc, t) => acc + (t.plannedDistanceKm ?? 0), 0);
      const tripFuel = vehicleTrips.reduce((acc, t) => acc + (t.fuelConsumedL ?? 0), 0);
      const manualFuel = fuelLogs.filter(f => f.vehicleId === vehicle.id).reduce((acc, f) => acc + f.liters, 0);
      const totalFuel = tripFuel + manualFuel;
      const fuelEfficiency = totalFuel > 0 ? Number((totalDistance / totalFuel).toFixed(2)) : 0;

      return {
        vehicleId: vehicle.id,
        name: vehicle.name,
        registrationNumber: vehicle.registrationNumber,
        totalDistance,
        totalFuel,
        fuelEfficiency
      };
    });
    res.json(data);
  });

  app.get("/api/reports/operational-cost", (req, res) => {
    const vehicles = db.getVehicles();
    const mLogs = db.getMaintenanceLogs();
    const fuelLogs = db.getFuelLogs();
    const expenses = db.getExpenses();

    const data = vehicles.map(vehicle => {
      const fuelCost = fuelLogs.filter(f => f.vehicleId === vehicle.id).reduce((acc, f) => acc + f.cost, 0);
      const maintenanceCost = mLogs.filter(m => m.vehicleId === vehicle.id).reduce((acc, m) => acc + m.cost, 0);
      const otherExpenses = expenses.filter(e => e.vehicleId === vehicle.id).reduce((acc, e) => acc + e.amount, 0);
      const totalOperationalCost = fuelCost + maintenanceCost + otherExpenses;

      return {
        vehicleId: vehicle.id,
        name: vehicle.name,
        registrationNumber: vehicle.registrationNumber,
        fuelCost,
        maintenanceCost,
        otherExpenses,
        totalOperationalCost
      };
    });
    res.json(data);
  });

  app.get("/api/reports/roi", (req, res) => {
    const vehicles = db.getVehicles();
    const trips = db.getTrips();
    const mLogs = db.getMaintenanceLogs();
    const fuelLogs = db.getFuelLogs();
    const expenses = db.getExpenses();

    const data = vehicles.map(vehicle => {
      const fuelCost = fuelLogs.filter(f => f.vehicleId === vehicle.id).reduce((acc, f) => acc + f.cost, 0);
      const maintenanceCost = mLogs.filter(m => m.vehicleId === vehicle.id).reduce((acc, m) => acc + m.cost, 0);
      const otherExpenses = expenses.filter(e => e.vehicleId === vehicle.id).reduce((acc, e) => acc + e.amount, 0);
      const totalOperationalCost = fuelCost + maintenanceCost + otherExpenses;

      const totalRevenue = trips.filter(t => t.vehicleId === vehicle.id && t.status === TripStatus.COMPLETED)
                                .reduce((acc, t) => acc + (t.revenue ?? 0), 0);

      const netEarnings = totalRevenue - totalOperationalCost;
      const roiPercent = vehicle.acquisitionCost > 0
        ? Number(((netEarnings / vehicle.acquisitionCost) * 100).toFixed(2))
        : 0;

      return {
        vehicleId: vehicle.id,
        name: vehicle.name,
        registrationNumber: vehicle.registrationNumber,
        acquisitionCost: vehicle.acquisitionCost,
        totalRevenue,
        totalOperationalCost,
        roiPercent
      };
    });
    res.json(data);
  });

  app.get("/api/reports/export.csv", (req, res) => {
    const vehicles = db.getVehicles();
    const trips = db.getTrips();
    const mLogs = db.getMaintenanceLogs();
    const fuelLogs = db.getFuelLogs();
    const expenses = db.getExpenses();

    let csv = "Vehicle ID,Name,Registration Number,Type,Total Distance (km),Total Fuel (L),Fuel Efficiency (km/L),Operational Cost ($),Total Revenue ($),ROI (%)\n";
    vehicles.forEach(vehicle => {
      const vehicleTrips = trips.filter(t => t.vehicleId === vehicle.id && t.status === TripStatus.COMPLETED);
      const totalDistance = vehicleTrips.reduce((sum, t) => sum + (t.plannedDistanceKm ?? 0), 0);
      const tripFuel = vehicleTrips.reduce((sum, t) => sum + (t.fuelConsumedL ?? 0), 0);
      const manualFuel = fuelLogs.filter(f => f.vehicleId === vehicle.id).reduce((sum, f) => sum + f.liters, 0);
      const totalFuel = tripFuel + manualFuel;
      const kmPerL = totalFuel > 0 ? (totalDistance / totalFuel).toFixed(2) : "0.00";

      const fuelCost = fuelLogs.filter(f => f.vehicleId === vehicle.id).reduce((sum, f) => sum + f.cost, 0);
      const maintenanceCost = mLogs.filter(m => m.vehicleId === vehicle.id).reduce((sum, m) => sum + m.cost, 0);
      const vehicleExpenses = expenses.filter(e => e.vehicleId === vehicle.id).reduce((sum, e) => sum + e.amount, 0);
      const opCost = fuelCost + maintenanceCost + vehicleExpenses;

      const totalRevenue = trips.filter(t => t.vehicleId === vehicle.id && t.status === TripStatus.COMPLETED)
                                .reduce((sum, t) => sum + (t.revenue ?? 0), 0);
      const roiVal = vehicle.acquisitionCost > 0
        ? (((totalRevenue - opCost) / vehicle.acquisitionCost) * 100).toFixed(2)
        : "0.00";

      csv += `"${vehicle.id}","${vehicle.name}","${vehicle.registrationNumber}","${vehicle.type}",${totalDistance},${totalFuel},${kmPerL},${opCost},${totalRevenue},${roiVal}\n`;
    });

    res.setHeader("Content-Type", "text/csv");
    res.setHeader("Content-Disposition", "attachment; filename=fleet_analytics_report.csv");
    res.status(200).send(csv);
  });

  // --- INTEGRATION WITH VITE FRONTEND ---

  if (!isProd) {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa"
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`TransitOps server running at http://localhost:${PORT}`);
  });
}

startServer();
